<?php
declare(strict_types=1);
require_once __DIR__ . '/auth.php';
require_once __DIR__ . '/category_inventory_helpers.php';
require_once __DIR__ . '/hardware_assignment_helpers.php';
requirePermission('inventory', 'view');
requirePermission('products', 'view');

$view = (string)($_GET['view'] ?? '');
$allowed = ['active_products','categories','available_stock','low_stock','category_active','category_inactive','category_total'];
if (!in_array($view, $allowed, true)) { http_response_code(404); exit('Details page not found'); }
if (in_array($view, ['category_active','category_inactive','category_total'], true)) {
    requirePermission('assignments', 'view'); requirePermission('employees', 'view');
    if ($view !== 'category_active') requirePermission('hardware', 'view');
}
if (in_array($view, ['active_products','categories','available_stock','low_stock'], true)) { requirePermission('assignments','view'); requirePermission('employees','view'); }
if (in_array($view, ['category_inactive','category_total','available_stock'], true)) requirePermission('hardware','view');
$pdo=db(); $safe=static fn(mixed $v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
$assignedQuantitySql=activeHardwareAssignmentQuantitySql('a'); $validAssignedEmployeeSql=activeHardwareAssignmentEmployeeSql('a');
$categoryId=filter_var($_GET['category_id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]])?:0;
$subcategoryId=filter_var($_GET['sub_category_id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]])?:0;
$productId=filter_var($_GET['product_id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]])?:0;
$search=trim((string)($_GET['q']??'')); $page=max(1,(int)($_GET['page']??1)); $perPage=50;
$sort=(string)($_GET['sort']??'category');$direction=strtolower((string)($_GET['direction']??'asc'))==='desc'?'DESC':'ASC';
$sortColumns=$view==='categories'?['category'=>'c.name','products'=>'product_count','available'=>'available_quantity','assigned'=>'assigned_quantity']:['category'=>'c.name','product'=>'p.name','available'=>'available_quantity','assigned'=>'assigned_quantity','minimum'=>'p.minimum_stock'];
if(!isset($sortColumns[$sort]))$sort=$view==='categories'?'category':'category';
$categories=$pdo->query('SELECT id,name FROM categories ORDER BY name,id')->fetchAll();
$subcategories=[]; if($categoryId){$s=$pdo->prepare('SELECT id,name FROM sub_categories WHERE category_id=? ORDER BY name,id');$s->execute([$categoryId]);$subcategories=$s->fetchAll();}
$params=[]; $where=[];
if($categoryId){$where[]='p.category_id=?';$params[]=$categoryId;}
if($subcategoryId){$where[]='p.sub_category_id=?';$params[]=$subcategoryId;}
if($productId){$where[]='p.id=?';$params[]=$productId;}
if($search!==''){$where[]='(p.name LIKE ? OR p.brand LIKE ? OR p.model LIKE ? OR c.name LIKE ? OR sc.name LIKE ?)';array_push($params,...array_fill(0,5,'%'.$search.'%'));}
if($view==='active_products')$where[]='p.active=1';
if($view==='low_stock')$where[]='p.active=1 AND COALESCE(st.available_quantity,0)<=p.minimum_stock';
if($view==='available_stock')$where[]='p.active=1';
$whereSql=$where?' WHERE '.implode(' AND ',$where):'';
$base=" FROM products p JOIN categories c ON c.id=p.category_id LEFT JOIN sub_categories sc ON sc.id=p.sub_category_id LEFT JOIN (SELECT product_id,new_quantity AS available_quantity FROM (SELECT product_id,new_quantity,ROW_NUMBER() OVER(PARTITION BY product_id ORDER BY transaction_at DESC,id DESC) rn FROM inventory_transactions) latest_stock WHERE rn=1) st ON st.product_id=p.id LEFT JOIN (SELECT a.product_id,SUM($assignedQuantitySql) assigned_quantity FROM assignments a WHERE a.status='assigned' AND a.returned_at IS NULL AND $validAssignedEmployeeSql GROUP BY a.product_id) assigned ON assigned.product_id=p.id";
$count=$pdo->prepare($view==='categories'?'SELECT COUNT(*) FROM categories c WHERE c.active=1':'SELECT COUNT(*)'.$base.$whereSql);$count->execute($view==='categories'?[]:$params);$totalRows=(int)$count->fetchColumn();$pages=max(1,(int)ceil($totalRows/$perPage));$page=min($page,$pages);$offset=($page-1)*$perPage;
if($view==='categories'){$query=$pdo->prepare("SELECT c.id category_id,c.name category_name,COUNT(p.id) product_count,COALESCE(SUM(COALESCE(st.available_quantity,0)),0) available_quantity,COALESCE(SUM(COALESCE(assigned.assigned_quantity,0)),0) assigned_quantity FROM categories c LEFT JOIN products p ON p.category_id=c.id LEFT JOIN (SELECT product_id,new_quantity available_quantity FROM (SELECT product_id,new_quantity,ROW_NUMBER() OVER(PARTITION BY product_id ORDER BY transaction_at DESC,id DESC) rn FROM inventory_transactions) x WHERE rn=1) st ON st.product_id=p.id LEFT JOIN (SELECT a.product_id,SUM($assignedQuantitySql) assigned_quantity FROM assignments a WHERE a.status='assigned' AND a.returned_at IS NULL AND $validAssignedEmployeeSql GROUP BY a.product_id) assigned ON assigned.product_id=p.id WHERE c.active=1 GROUP BY c.id,c.name ORDER BY ".$sortColumns[$sort]." $direction,c.id LIMIT $perPage OFFSET $offset");$query->execute();$rows=$query->fetchAll();}
else{$query=$pdo->prepare('SELECT p.id,p.name,p.brand,p.model,p.category_id,p.sub_category_id,p.active,p.minimum_stock,c.name category_name,sc.name subcategory_name,COALESCE(st.available_quantity,0) available_quantity,COALESCE(assigned.assigned_quantity,0) assigned_quantity'. $base.$whereSql.' ORDER BY '.$sortColumns[$sort].' '.$direction.',p.id LIMIT '.$perPage.' OFFSET '.$offset);$query->execute($params);$rows=$query->fetchAll();}
$title=match($view){'active_products'=>'Active products','categories'=>'Categories and stock breakdown','available_stock'=>'Available inventory by category and product','low_stock'=>'Low or out of stock','category_active'=>'Assigned hardware','category_inactive'=>'Available inventory','category_total'=>'Total category inventory'};
$pageTitle=$title; require __DIR__.'/header.php';
?>
<section class="category-detail-section">
<div class="category-detail-heading"><div><div class="eyebrow">DASHBOARD DETAILS</div><h2><?=$safe($title)?></h2></div><div class="drilldown-nav"><a class="btn" href="dashboard.php">Back to Dashboard</a><?php if($categoryId):?><a class="btn" href="category-inventory.php?category_id=<?=$categoryId?>">Back to Category</a><?php endif;?></div></div>
<form method="get" class="toolbar category-detail-filters"><input type="hidden" name="view" value="<?=$safe($view)?>"><div><label for="dd-category">Category</label><select id="dd-category" name="category_id"><option value="">All categories</option><?php foreach($categories as $c):?><option value="<?=$c['id']?>" <?=$categoryId===(int)$c['id']?'selected':''?>><?=$safe($c['name'])?></option><?php endforeach;?></select></div><?php if($categoryId):?><div><label for="dd-subcategory">Sub-category</label><select id="dd-subcategory" name="sub_category_id"><option value="">All sub-categories</option><?php foreach($subcategories as $sc):?><option value="<?=$sc['id']?>" <?=$subcategoryId===(int)$sc['id']?'selected':''?>><?=$safe($sc['name'])?></option><?php endforeach;?></select></div><?php endif;?><div><label for="dd-search">Search</label><input id="dd-search" name="q" value="<?=$safe($search)?>" placeholder="Product, brand, model"></div><div><label for="dd-sort">Sort by</label><select id="dd-sort" name="sort"><?php foreach($sortColumns as $key=>$column):?><option value="<?=$safe($key)?>" <?=$sort===$key?'selected':''?>><?=$safe(ucfirst($key))?></option><?php endforeach;?></select></div><div><label for="dd-direction">Direction</label><select id="dd-direction" name="direction"><option value="asc" <?=$direction==='ASC'?'selected':''?>>Ascending</option><option value="desc" <?=$direction==='DESC'?'selected':''?>>Descending</option></select></div><button class="btn" type="submit">Apply filters</button></form>
<p class="muted">Showing <?=count($rows)?> of <?=$totalRows?> products · page <?=$page?> of <?=$pages?></p>
<div class="table-scroll"><table><thead><?php if($view==='categories'):?><tr><th>Category</th><th>Active products</th><th>Assigned units</th><th>Available units</th><th>Total physical units</th><th>Details</th></tr><?php else:?><tr><th>Product</th><th>Brand</th><th>Model</th><th>Category</th><th>Sub-category</th><th>Assigned</th><th>Available</th><th>Minimum</th><th>Shortage</th><th>Status</th><th>Details</th></tr><?php endif;?></thead><tbody>
<?php if($view==='categories'):foreach($rows as $r):?><tr><td><?=$safe($r['category_name'])?></td><td><?=number_format((int)$r['product_count'])?></td><td><?=number_format((int)$r['assigned_quantity'])?></td><td><?=number_format((int)$r['available_quantity'])?></td><td><?=number_format((int)$r['assigned_quantity']+(int)$r['available_quantity'])?></td><td><a class="btn" href="category-inventory.php?category_id=<?=(int)$r['category_id']?>">Open category</a></td></tr><?php endforeach;?>
<?php else:foreach($rows as $r):$available=(int)$r['available_quantity'];$assigned=(int)$r['assigned_quantity'];$short=max(0,(int)$r['minimum_stock']-$available);?><tr><td><a href="inventory-details.php?<?=http_build_query(['view'=>'product','category_id'=>(int)$r['category_id'],'product_id'=>(int)$r['id']])?>"><?=$safe($r['name'])?></a></td><td><?=$safe($r['brand']?:'—')?></td><td><?=$safe($r['model']?:'—')?></td><td><?=$safe($r['category_name'])?></td><td><?=$safe($r['subcategory_name']?:'—')?></td><td><?=number_format($assigned)?></td><td><?=number_format($available)?></td><td><?=number_format((int)$r['minimum_stock'])?></td><td><?=number_format($short)?></td><td><?=$r['active']?'Active':'Inactive'?></td><td><a class="btn" href="inventory-details.php?<?=http_build_query(['view'=>'total','category_id'=>(int)$r['category_id'],'product_id'=>(int)$r['id']])?>">View stock</a></td></tr><?php endforeach;endif;?>
<?php if(!$rows):?><tr><td colspan="11" class="empty-state">No matching inventory records.</td></tr><?php endif;?></tbody></table></div>
<?php if(in_array($view,['category_active','category_inactive','category_total'],true)&&$rows):?>
<?php $ids=array_map(static fn($r)=>(int)$r['id'],$rows);$marks=implode(',',array_fill(0,count($ids),'?'));$showAssigned=$view!=='category_inactive';$showAvailable=$view!=='category_active';?>
<?php if($showAssigned):?><h3 class="section-spaced">Assigned hardware and employees</h3><div class="table-scroll"><table><thead><tr><th>Product</th><th>Brand / Model</th><th>Employee</th><th>Employee ID</th><th>Asset tag</th><th>Serial</th><th>Assignment date</th><th>Quantity</th><th>Location</th></tr></thead><tbody><?php $q=$pdo->prepare("SELECT p.name,p.brand,p.model,$assignedQuantitySql quantity,a.assigned_at,COALESCE(e.full_name,a.assigned_to) employee_name,COALESCE(e.employee_id,a.employee_id,'—') employee_code,COALESCE(ia.asset_tag,'—') asset_tag,COALESCE(ia.serial_number,'—') serial_number,COALESCE(e.location,a.location,'—') location FROM assignments a JOIN products p ON p.id=a.product_id LEFT JOIN employees e ON e.id=a.employee_record_id LEFT JOIN inventory_assets ia ON ia.id=a.asset_id WHERE a.product_id IN ($marks) AND a.status='assigned' AND a.returned_at IS NULL AND $validAssignedEmployeeSql ORDER BY a.assigned_at DESC,a.id DESC");$q->execute($ids);$items=$q->fetchAll();foreach($items as $it):?><tr><td><?=$safe($it['name'])?></td><td><?=$safe(trim(($it['brand']??'').' '.($it['model']??''))?:'—')?></td><td><?=$safe($it['employee_name'])?></td><td><?=$safe($it['employee_code'])?></td><td><?=$safe($it['asset_tag'])?></td><td><?=$safe($it['serial_number'])?></td><td><?=$safe($it['assigned_at'])?></td><td><?=number_format((int)$it['quantity'])?></td><td><?=$safe($it['location'])?></td></tr><?php endforeach;?><?php if(!$items):?><tr><td colspan="9" class="empty-state">No active assignments.</td></tr><?php endif;?></tbody></table></div><?php endif;?>
<?php if($showAvailable):?><h3 class="section-spaced">Available registered hardware and bulk stock</h3><div class="table-scroll"><table><thead><tr><th>Product</th><th>Brand</th><th>Model</th><th>Sub-category</th><th>Asset tag</th><th>Serial</th><th>Location</th><th>Available counted</th></tr></thead><tbody><?php $aq=$pdo->prepare("SELECT p.id,p.name,p.brand,p.model,sc.name subcategory_name,COALESCE(st.available_quantity,0) ledger_qty,ia.asset_tag,ia.serial_number,ia.location FROM products p LEFT JOIN sub_categories sc ON sc.id=p.sub_category_id LEFT JOIN inventory_assets ia ON ia.product_id=p.id AND ia.status='available' AND NOT EXISTS(SELECT 1 FROM assignments a WHERE a.asset_id=ia.id AND a.status='assigned' AND a.returned_at IS NULL) AND NOT EXISTS(SELECT 1 FROM active_hardware_assignments aha WHERE aha.asset_id=ia.id) LEFT JOIN (SELECT product_id,new_quantity available_quantity FROM (SELECT product_id,new_quantity,ROW_NUMBER() OVER(PARTITION BY product_id ORDER BY transaction_at DESC,id DESC) rn FROM inventory_transactions) z WHERE rn=1) st ON st.product_id=p.id WHERE p.id IN ($marks) ORDER BY p.name,ia.asset_tag");$aq->execute($ids);$assetRows=$aq->fetchAll();$assetCounts=[];foreach($assetRows as $ar){$assetCounts[$ar['id']]=($assetCounts[$ar['id']]??0)+($ar['asset_tag']!==null?1:0);if($ar['asset_tag']!==null):?><tr><td><?=$safe($ar['name'])?></td><td><?=$safe($ar['brand']?:'—')?></td><td><?=$safe($ar['model']?:'—')?></td><td><?=$safe($ar['subcategory_name']?:'—')?></td><td><?=$safe($ar['asset_tag'])?></td><td><?=$safe($ar['serial_number']?:'—')?></td><td><?=$safe($ar['location']?:'—')?></td><td>1</td></tr><?php endif; } foreach($rows as $pr){$bulk=max(0,(int)$pr['available_quantity']-($assetCounts[$pr['id']]??0));if($bulk):?><tr><td><?=$safe($pr['name'])?></td><td><?=$safe($pr['brand']?:'—')?></td><td><?=$safe($pr['model']?:'—')?></td><td><?=$safe($pr['subcategory_name']?:'—')?></td><td colspan="3">Unregistered bulk stock</td><td><?=number_format($bulk)?></td></tr><?php endif;}?><?php if(!$assetRows):?><tr><td colspan="8" class="empty-state">No available inventory.</td></tr><?php endif;?></tbody></table></div><?php endif;?><?php endif;?>
<?php if($view==='available_stock'&&$rows&&canViewResource('hardware')):?><h3 class="section-spaced">Registered available units</h3><div class="table-scroll"><table><thead><tr><th>Product</th><th>Category</th><th>Brand</th><th>Model</th><th>Asset tag</th><th>Serial number</th><th>Location</th><th>Counted</th></tr></thead><tbody><?php $ids=array_map(static fn($r)=>(int)$r['id'],$rows);$marks=implode(',',array_fill(0,count($ids),'?'));$assetsQuery=$pdo->prepare("SELECT ia.product_id,p.name,c.name category_name,p.brand,p.model,ia.asset_tag,ia.serial_number,ia.location FROM inventory_assets ia JOIN products p ON p.id=ia.product_id JOIN categories c ON c.id=p.category_id WHERE ia.product_id IN ($marks) AND ia.status='available' AND NOT EXISTS(SELECT 1 FROM assignments a WHERE a.asset_id=ia.id AND a.status='assigned' AND a.returned_at IS NULL) AND NOT EXISTS(SELECT 1 FROM active_hardware_assignments aha WHERE aha.asset_id=ia.id) ORDER BY c.name,p.name,ia.asset_tag");$assetsQuery->execute($ids);$assets=$assetsQuery->fetchAll();$availableByProduct=[];$registeredByProduct=[];foreach($rows as $pRow)$availableByProduct[(int)$pRow['id']]=(int)$pRow['available_quantity'];foreach($assets as $asset):$pid=(int)$asset['product_id'];$counted=(($registeredByProduct[$pid]??0)<($availableByProduct[$pid]??0));$registeredByProduct[$pid]=($registeredByProduct[$pid]??0)+1;?><tr><td><?=$safe($asset['name'])?></td><td><?=$safe($asset['category_name'])?></td><td><?=$safe($asset['brand']?:'—')?></td><td><?=$safe($asset['model']?:'—')?></td><td><?=$safe($asset['asset_tag'])?></td><td><?=$safe($asset['serial_number']?:'—')?></td><td><?=$safe($asset['location']?:'—')?></td><td><?=$counted?'1':'0 (outside ledger balance)'?></td></tr><?php endforeach;?><?php if(!$assets):?><tr><td colspan="8" class="empty-state">No individually registered available units on this page.</td></tr><?php endif;?></tbody></table></div><h3>Unregistered or bulk available stock</h3><div class="table-scroll"><table><thead><tr><th>Product</th><th>Category</th><th>Bulk quantity</th></tr></thead><tbody><?php $bulkCount=0;foreach($rows as $pRow){$pid=(int)$pRow['id'];$bulk=max(0,(int)$pRow['available_quantity']-min((int)$pRow['available_quantity'],(int)($registeredByProduct[$pid]??0)));if($bulk){$bulkCount+=$bulk;?><tr><td><?=$safe($pRow['name'])?></td><td><?=$safe($pRow['category_name'])?></td><td><?=number_format($bulk)?></td></tr><?php }}if(!$bulkCount):?><tr><td colspan="3" class="empty-state">No unregistered or bulk units are counted.</td></tr><?php endif;?></tbody></table></div><?php endif;?>
<nav class="pagination" aria-label="Pages"><?php for($n=1;$n<=$pages;$n++):$link=$_GET;$link['page']=$n;?><a class="btn <?=$n===$page?'active':''?>" href="?<?=http_build_query($link)?>" <?=$n===$page?'aria-current="page"':''?>><?=$n?></a><?php endfor;?></nav>
</section><?php require __DIR__.'/footer.php'; ?>
